<template><DashboardLayout title="Kelola User" role-label="Admin" :navigation="nav"><UiAlert v-if="error" type="danger" class="mb-4" :dismissible="false">{{error}}</UiAlert><UiCard title="User" subtitle="Kelola akun dan role pengguna." :padded="false"><template #actions><UiButton @click="open()">Tambah user</UiButton></template><UiTable :columns="cols" :rows="items" :loading="loading"><template #empty><p class="font-medium text-slate-600">Belum ada user</p></template><template #row="{row}"><td class="px-6 py-4 font-medium">{{row.name}}</td><td class="px-6 py-4">{{row.email}}</td><td class="px-6 py-4"><UiBadge variant="neutral">{{row.role}}</UiBadge></td><td class="px-6 py-4"><UiBadge :variant="row.is_active?'success':'danger'">{{row.is_active?'Aktif':'Nonaktif'}}</UiBadge></td><td class="px-6 py-4 text-right"><UiButton size="sm" variant="ghost" @click="open(row)">Edit</UiButton></td></template></UiTable></UiCard><UiModal v-model="show" :title="edit?'Edit user':'Tambah user'"><form id="user-form" class="grid gap-4 sm:grid-cols-2" @submit.prevent="save"><UiInput v-model="form.name" label="Nama" required :error="err('name')"/><UiInput v-model="form.email" label="Email" type="email" required :error="err('email')"/><UiInput v-model="form.password" class="sm:col-span-2" label="Password" type="password" :required="!edit" hint="Minimal 8 karakter; kosongkan saat edit bila tidak diubah." :error="err('password')"/><UiSelect v-model="form.role" label="Role" :options="roles" required :error="err('role')"/><UiSelect v-model="form.is_active" label="Status" :options="states"/><UiInput v-if="form.role==='Guru'" v-model="form.nip" label="NIP" required :error="err('nip')"/><UiInput v-if="form.role==='Murid'" v-model="form.nis" label="NIS" required :error="err('nis')"/><UiSelect v-if="form.role==='Murid'" v-model="form.gender" label="Jenis kelamin" :options="gender" :error="err('gender')"/><UiInput v-if="form.role==='Murid'" v-model="form.tanggal_lahir" label="Tanggal lahir" type="date" :error="err('tanggal_lahir')"/><UiInput v-if="form.role==='Karyawan'" v-model="form.bagian" label="Bagian" required :error="err('bagian')"/></form><template #footer><UiButton variant="secondary" @click="show=false">Batal</UiButton><UiButton type="submit" form="user-form" :loading="saving">Simpan</UiButton></template></UiModal></DashboardLayout></template>
<script setup>
import{onMounted,reactive,ref}from'vue';import DashboardLayout from'@/components/dashboard/DashboardLayout.vue';import UiAlert from'@/components/ui/UiAlert.vue';import UiCard from'@/components/ui/UiCard.vue';import UiTable from'@/components/ui/UiTable.vue';import UiButton from'@/components/ui/UiButton.vue';import UiBadge from'@/components/ui/UiBadge.vue';import UiModal from'@/components/ui/UiModal.vue';import UiInput from'@/components/ui/UiInput.vue';import UiSelect from'@/components/ui/UiSelect.vue';import{adminUserApi as api}from'@/services/adminUserApi';const nav=[{label:'Dashboard',icon:'fas fa-chart-pie',to:'/dashboard/admin'},{label:'Kelola User',icon:'fas fa-users',to:'/dashboard/admin/users'},{label:'Kelola Mata Pelajaran',icon:'fas fa-book-open',to:'/dashboard/admin/mapel'}],cols=[{key:'n',label:'Nama'},{key:'e',label:'Email'},{key:'r',label:'Role'},{key:'s',label:'Status'},{key:'a',label:''}],roles=['Admin','Guru','Murid','Karyawan'].map(value=>({value,label:value})),states=[{value:'true',label:'Aktif'},{value:'false',label:'Nonaktif'}],gender=[{value:'L',label:'Laki-laki'},{value:'P',label:'Perempuan'}],items=ref([]),loading=ref(true),error=ref(''),show=ref(false),edit=ref(false),saving=ref(false),current=ref(),errors=ref({}),form=reactive({});const err=k=>errors.value[k]?.[0]??'';async function load(){loading.value=true;try{items.value=(await api.list()).data??[]}catch(e){error.value=e.response?.data?.message??'User gagal dimuat.'}finally{loading.value=false}}function open(u){edit.value=!!u;current.value=u;Object.assign(form,{name:u?.name??'',email:u?.email??'',password:'',role:u?.role??'Admin',is_active:String(u?.is_active??true),nip:'',nis:'',gender:'',tanggal_lahir:'',bagian:''});errors.value={};show.value=true}async function save(){saving.value=true;errors.value={};let d={...form,is_active:form.is_active==='true'};if(!d.password)delete d.password;try{let b=edit.value?await api.update(current.value.id,d):await api.create(d);if(edit.value)items.value=items.value.map(x=>x.id===b.data.id?b.data:x);else items.value.unshift(b.data);show.value=false}catch(e){errors.value=e.response?.data?.errors??{};error.value=e.response?.data?.message??'User gagal disimpan.'}finally{saving.value=false}}onMounted(load)
</script>
